"""The VJ frame (native/vj.py): two decks, each a video source and a look,
their previews side by side, a crossfader between them, the mix on air in
place of the effect - in the sim, so on the stream.

    vj_ui.build(app); vj_ui.refresh(app); vj_ui.poll(app)    # as the other frames
    vj_ui.browse(app, i)                                     # the looks as moving thumbnails, for deck i
    vj_ui.undo(app, redo=False)                              # the VJ's last change undone (Ctrl+Z in the frame)
"""
# AI: below section was generated by an AI
import math
import os
import time

import dearpygui.dearpygui as dpg
import numpy as np

from native import num, typeface, vj, vj_looks, weight
