def _build_browser(app):
    c = _c()
    with dpg.window(tag=BROWSE, show=False, no_title_bar=True, no_collapse=True, width=px(560), height=px(520)):
        c.dialog_header(BROWSE, "Looks")
        dpg.add_text("", tag="vj_br_words", color=c.DIM)
        dpg.add_group(tag="vj_br_grid")


def _fill_browser(app):
    c = _c()
    dpg.delete_item("vj_br_grid", children_only=True)
    app._vj_thumbs = {}
    per_row = 6
    for fam, words in vj_looks.FAMILIES:
        names = [n for n, lk in vj_looks.LOOKS.items() if lk.family == fam]
        if not names:
            continue
        typeface.label(dpg.add_text(words.upper(), color=c.ACCENT, parent="vj_br_grid"))
        row = None
        for k, n in enumerate(names):
            if k % per_row == 0:
                row = dpg.add_group(horizontal=True, parent="vj_br_grid")
            tag = f"vj_th_{abs(hash(n)) % 10 ** 9}"
            _tex(tag, TH_W, TH_H)
            with dpg.group(parent=row):
                dpg.add_image_button(tag, width=px(TH_W * 1.4), height=px(TH_H * 1.4),
                                     callback=lambda s, a, u: _browse_pick(app, u), user_data=n)
                c.tip(f"{n}: {vj_looks.LOOKS[n].desc}")
                dpg.add_text(n.replace("Drop: ", "").replace("Flame: ", "")[:11], color=c.DIM)
            app._vj_thumbs[n] = {"tag": tag, "state": {}, "t": 0.0}
    dpg.add_button(label="Effect", parent="vj_br_grid",
                   callback=lambda: _browse_pick(app, vj.EFFECT))


def browse(app, i):
    """The looks as moving thumbnails; a click puts one on deck i."""
    from native import chrome
    app._vj_browse_deck = i
    if not getattr(app, "_vj_thumbs", None) or set(app._vj_thumbs) != {n for n in vj_looks.LOOKS}:
        _fill_browser(app)
    dpg.set_value("vj_br_words", f"a click puts the look on deck {LETTER[i]}")
    chrome._centre(BROWSE, 560, 520)
    dpg.show_item(BROWSE)


def _browse_pick(app, name):
    i = getattr(app, "_vj_browse_deck", 0)
    _set_deck(app, i, "look", name)
    app.gp.status(f"deck {LETTER[i]}: {name}")


def _thumbs(app):
    """A few thumbnails a frame drawn, in turn: each its look at the thumbnail's size, the test pattern for video."""
    th = getattr(app, "_vj_thumbs", None)
    if not th or not dpg.is_item_shown(BROWSE):
        return
    from native import video
    if getattr(app, "_vj_th_src", None) is None:
        app._vj_th_src = video.TestPattern(TH_W, TH_H)
        app._vj_th_ctx = None
    names = list(th)
    k0 = getattr(app, "_vj_th_k", 0)
    now = time.perf_counter()
    snd = vj.sound(app)
    for j in range(5):
        n = names[(k0 + j) % len(names)]
        e = th[n]
        lk = vj_looks.LOOKS.get(n)
        if lk is None:
            continue
        dt = min(0.25, now - e.get("at", now)) if e.get("at") else 1 / 30
        e["at"] = now
        e["t"] += dt
        c = vj.Ctx()
        c.w, c.h = TH_W, TH_H
        c.u, c.v, c.x, c.y, c.r, c.a = vj._grid(TH_W, TH_H)
        c.t, c.dt = e["t"], dt
        c.bass, c.mid, c.treb, c.level, c.wave = snd
        # a beat of their own, twice a second: a look that waits for beats is not dark in its thumbnail
        ph = (e["t"] * 2.0) % 1.0
        c.beat = math.exp(-ph * 6.0)
        c.beat_hit = int(e["t"] * 2.0) != int((e["t"] - dt) * 2.0)
        c.beats = getattr(app, "_vj_beats", 0.0)
        c.deck = {"text": "WLED", "image": ""}
        vid = app._vj_th_src.frame_at(e["t"]).astype(np.float32) / 255.0
        c.video, c.video_prev = vid, e.get("prev")
        e["prev"] = vid
        c.amount, c.speed = 0.5, 1.0
        c.grad = vj_looks.gradient("neon")
        try:
            img = np.clip(lk.draw(c, e["state"]), 0, 1)
        except Exception:
            img = np.zeros((TH_H, TH_W, 3), np.float32)
        if img.shape[:2] != (TH_H, TH_W):
            continue
        dpg.set_value(e["tag"], np.concatenate([img, np.ones((TH_H, TH_W, 1), np.float32)], -1).ravel())
    app._vj_th_k = (k0 + 5) % max(1, len(names))


# --- changes -------------------------------------------------------------------------------------
def _save(app, now=False):
    """Saved once the change settles: a drag is one undo step."""
    app._vj_save_at = time.perf_counter() + (0.0 if now else SAVE_AFTER)


def _flush_save(app, now=False):
    t = getattr(app, "_vj_save_at", None)
    if t is not None and (now or time.perf_counter() >= t):
        app._vj_save_at = None
        app.project.save()


def undo(app, redo=False):
    """The VJ as it was before its last change (or again after an undo)."""
    _flush_save(app, now=True)
    p = app.project
    ok = p.redo("vj") if redo else p.undo("vj")
    if not ok:
        app.gp.status("nothing to " + ("redo" if redo else "undo") + " in the VJ"); return
    vj.options(app)
    refresh(app)
    app.gp.status("VJ: " + ("redo" if redo else "undo"))


def _set(app, key, v):
    vj.options(app)[key] = v
    _save(app)


def _set_auto(app, key, v):
    vj.options(app)["auto"][key] = v
    _save(app)


def set_on(app, v):
    vj.options(app)["on"] = bool(v)
    if dpg.does_item_exist("vj_on") and dpg.get_value("vj_on") != bool(v):
        dpg.set_value("vj_on", bool(v))
    _save(app)
    app.gp.status("the VJ is on air" if v else "the VJ is off air: the effect shows again")


def _set_deck(app, i, key, v):
    vj.options(app)["decks"][i][key] = v
    _save(app)
    if key in ("look", "effect", "image"):
        refresh(app)


def _set_channel(app, i, k, v):
    d = vj.options(app)["decks"][i]
    ch = list(d.get("channels") or ["", "", "", ""])
    ch[k] = "" if v.startswith("file:") else v
    d["channels"] = ch
    _save(app)
    refresh(app)                                                     # a picture chosen: its row shown


def _set_react(app, i, **kw):
    vj.options(app)["decks"][i]["react"].update(kw)
    _save(app)


def _set_src(app, i, **kw):
    s = vj.options(app)["decks"][i]["source"]
    s.update({k: v for k, v in kw.items() if v is not None})
    _save(app)
    if not {"speed", "in", "out"} & set(kw):
        refresh(app)


def _add_files(app, i, a):
    """Files from the dialog onto the deck's list (several at once), copied into the project's assets/vj first -
    on a worker, a video can be large - so the project keeps them."""
    from native import tasks
    sel = [f for f in (list((a.get("selections") or {}).values()) or [a.get("file_path_name", "")]) if f and os.path.isfile(f)]
    if not sel:
        return

    def work():
        return [vj.keep_media(app, f) for f in sel]

    def done(kept):
        s = vj.options(app)["decks"][i]["source"]
        files = [f for f in (s.get("files") or []) if f]
        if not files and s.get("path"):
            files = [s["path"]]
        added = [f for f in kept if f not in files]
        s["files"] = files + added
        if added:
            s["clip"] = len(files)                                  # the first one added plays
        s["kind"] = "file"
        _save(app)
        refresh(app)
        app.gp.status(f"{len(kept)} video file(s) kept in the project's {vj.MEDIA_DIR}")
    tasks.run(app, f"vj_files{i}", f"copying {len(sel)} video file(s) into the project", work, done)


def _set_image(app, i, path):
    if not path or not os.path.isfile(path):
        return
    try:
        kept = vj.keep_media(app, path)
    except OSError as e:
        app.gp.status(f"could not copy {os.path.basename(path)}: {e}", "warn"); return
    _set_deck(app, i, "image", kept)


def _import(app, a):
    """.milk presets and .glsl shaders copied into the project's looks/ and listed."""
    sel = [f for f in (list((a.get("selections") or {}).values()) or [a.get("file_path_name", "")]) if f and os.path.isfile(f)]
    for f in sel:
        vj_looks.import_file(app.project, f)
    errs = vj_looks.load_user(app.project, allow_py=py_allowed(app))
    app._vj_file_errs = errs
    app._vj_thumbs = None
    refresh(app)
    bad = [e for e in errs if any(os.path.basename(f).lower() in e[0].lower() for f in sel)]
    app.gp.status(f"{len(sel)} imported into the project's looks/" + (f" - {len(bad)} could not be read" if bad else ""))


def _new_shader(app):
    def made(name):
        name = (name or "").strip()
        if not name:
            return
        ok, why = __import__("native.vj_glsl", fromlist=["g"]).available()
        path = vj_looks.new_shader(app.project, name)
        vj_looks.load_user(app.project, allow_py=py_allowed(app))
        o = vj.options(app)
        cue = vj.cue_deck(app)
        lk = next((n for n, l in vj_looks.LOOKS.items() if l.family == "yours" and _user_path(n) == path), None)
        if lk:
            o["decks"][cue]["look"] = lk
        _save(app)
        refresh(app)
        _open(app, path)
        app.gp.status(f"{os.path.basename(path)} made in the project's looks/ - on deck {LETTER[cue]}"
                      + ("" if ok else f" (it will not run here: {why})"))
    _c().ask(app, "A shader of your own", "its name", "My shader", made)


def _pick_clip(app, i, label):
    s = vj.options(app)["decks"][i]["source"]
    names = [os.path.basename(f) for f in s.get("files") or []]
    if label in names:
        s["clip"] = names.index(label)
        _save(app)


def _drop_clip(app, i):
    s = vj.options(app)["decks"][i]["source"]
    files = list(s.get("files") or [])
    if files:
        del files[int(s.get("clip", 0)) % len(files)]
        s["files"] = files
        s["clip"] = 0
        _save(app)
        refresh(app)


def _default_preset(app, i):
    d = vj.options(app)["decks"][i]
    return (d["effect"] if d["look"] == vj.EFFECT else d["look"]) + " " + d["colours"]


def _save_preset(app, i, name):
    name = (name or "").strip()
    if not name:
        return
    vj.save_preset(app, i, name)
    _save(app)
    refresh(app)
    app.gp.status(f"VJ preset saved: {name}")


def _load_preset(app, i, name):
    vj.load_preset(app, i, name)
    _save(app)
    refresh(app)


def _rename_preset(app, i):
    old = dpg.get_value(f"vj_pre{i}")
    if not old:
        app.gp.status("pick a preset to rename"); return

    def done(new):
        if vj.rename_preset(app, old, new):
            _save(app); refresh(app); dpg.set_value(f"vj_pre{i}", new.strip())
        else:
            app.gp.status("a preset needs a name no other has")
    _c().ask(app, "Rename the preset", "its new name", old, done)


def _delete_preset(app, i):
    name = dpg.get_value(f"vj_pre{i}")
    if name and vj.delete_preset(app, name):
        _save(app)
        refresh(app)
        dpg.set_value(f"vj_pre{i}", "")
        app.gp.status(f"preset {name} deleted (undo brings it back)")


def _mutate(app, i):
    name = vj.mutate_flame(app, i)
    if name:
        _save(app)
        refresh(app)
        app.gp.status(f"bred {name}")


def _rename_flame(app, i):
    old = vj.options(app)["decks"][i]["look"]

    def done(new):
        if vj.rename_flame(app, old, new):
            _save(app); refresh(app)
        else:
            app.gp.status("a flame needs a name no look has")
    _c().ask(app, "Rename the flame", "its new name", old, done)


def _forget_flame(app, i):
    name = vj.options(app)["decks"][i]["look"]
    if vj.forget_flame(app, name):
        _save(app)
        refresh(app)
        app.gp.status(f"{name} forgotten (undo brings it back)")


def _tap(app):
    from native import sequence_ui
    sequence_ui.tap(app)


def _open(app, path):
    """A file in the editor the studio is set to use, else the system's."""
    import shutil
    from native import procs
    cmd = app.editor_command()
    try:
        if cmd:
            procs.popen([c.replace("{file}", path).replace("{line}", "1") for c in cmd])
        elif hasattr(os, "startfile"):
            os.startfile(path)
        else:
            opener = shutil.which("xdg-open") or shutil.which("open")
            if opener:
                procs.popen([opener, path])
    except Exception as e:
        app.gp.status(f"could not open {os.path.basename(path)}: {e}", "warn")


def _new_look(app):
    def made(name):
        name = (name or "").strip()
        if not name:
            return
        path = vj_looks.new_user_look(app.project, name)
        if not py_allowed(app):
            allow_py(app, True)                                      # the look is the user's own: this project is allowed
        vj_looks.load_user(app.project)
        o = vj.options(app)
        cue = 1 if float(o["fader"]) < 0.5 else 0                  # the deck off the mix: seen in its preview first
        lk = next((n for n, l in vj_looks.LOOKS.items() if l.family == "yours" and _user_path(n) == path), None)
        if lk:
            o["decks"][cue]["look"] = lk
        _save(app)
        refresh(app)
        _open(app, path)
        app.gp.status(f"{os.path.basename(path)} made in the project's looks/ - on deck {LETTER[cue]}; save it to see it")
    _c().ask(app, "A look of your own", "its name", "My look", made)


def py_allowed(app):
    """Whether this project's Python looks may run: the projects allowed on this machine (the studio's own
    settings, never the project's - a project from elsewhere cannot allow itself)."""
    root = os.path.normcase(os.path.abspath(app.project.path))
    return root in {os.path.normcase(p) for p in app.prefs.get("vj_py_projects", [])}


def allow_py(app, on=True):
    from native.project import save_prefs
    root = os.path.normcase(os.path.abspath(app.project.path))
    have = [p for p in app.prefs.get("vj_py_projects", []) if os.path.normcase(p) != root]
    app.prefs["vj_py_projects"] = have + ([os.path.abspath(app.project.path)] if on else [])
    save_prefs(app.prefs)
    app._vj_files_at = 0.0                                           # read again now
    app._vj_dirty = True


def _ask_py(app):
    """A project with Python looks not yet allowed here: asked once a session whether to run them."""
    asked = app.__dict__.setdefault("_vj_py_asked", set())
    root = os.path.abspath(app.project.path)
    files = vj_looks.py_files(app.project)
    if not files or py_allowed(app) or root in asked:
        return
    asked.add(root)
    names = ", ".join(files[:4]) + (f" and {len(files) - 4} more" if len(files) > 4 else "")
    _c().confirm(app, "Python looks", f"This project has looks written in Python ({names}). A Python look is a program: "
                 "it runs on this computer as it is, as the project's graphs and effects do. Run them only if you trust "
                 "where the project came from.",
                 [("Run them", lambda: allow_py(app, True)), ("Not now", None)])


def _user_path(name):
    return next((p for p, e in vj_looks._USER.items() if e[1] == name), None)


def _edit_look(app, i):
    path = _user_path(vj.options(app)["decks"][i]["look"])
    if path:
        _open(app, path)


def _fade_to(app, v):
    vj.set_fader(app, v)
    num.set("vj_fader", v)


def _pick_source(app, i):
    """The chosen kind's own choice: files for the list, the cameras or screens to pick from, the address."""
    from native import video
    kind = vj.options(app)["decks"][i]["source"].get("kind", "none")
    if kind == "file":
        dpg.show_item(f"vj_file{i}")
    elif kind in ("webcam", "screen"):
        from native import tasks

        def work():                                         # ffmpeg asked on a worker: the studio does not stop
            return [n for n, _ in (video.webcams() if kind == "webcam" else video.screens())]

        def done(names):
            if not names:
                app.gp.status(f"no {'cameras' if kind == 'webcam' else 'screens'} found"); return
            dpg.configure_item(f"vj_srcname{i}", items=names, show=True)
            dpg.set_value(f"vj_srcname{i}", vj.options(app)["decks"][i]["source"].get("name") or names[0])
        tasks.run(app, f"vj_list{i}", "looking for " + ("cameras" if kind == "webcam" else "screens"), work, done)
    elif kind == "stream":
        dpg.configure_item(f"vj_url{i}", show=True)


def refresh(app):
    if not dpg.does_item_exist(TAG):
        return
    o = vj.options(app)
    dpg.set_value("vj_on", bool(o["on"]))
    dpg.set_value("vj_map", dict(vj.MAPS)[o["map"]])
    dpg.set_value("vj_canvas", dict(vj.CANVASES).get(o["canvas"], o["canvas"]))
    dpg.set_value("vj_mode", o["mode"])
    dpg.set_value("vj_wipe", o["wipe"])
    dpg.set_value("vj_auto", dict(AUTO)[o["auto"]["mix"]])
    dpg.set_value("vj_bars", f"{o['auto']['bars']} bars")
    dpg.set_value("vj_shuffle", bool(o["auto"]["shuffle"]))
    dpg.set_value("vj_cue", bool(o.get("cue")))
    dpg.set_value("vj_cmode", o.get("c_mode", "screen"))
    pals = [OWN_PAL] + [n for n, _ in app.eng.palette_list()]
    for i in range(vj.DECKS):
        d = o["decks"][i]
        s = d["source"]
        eff = d["look"] == vj.EFFECT
        lk = vj_looks.LOOKS.get(d["look"])
        dpg.configure_item(f"vj_look{i}", items=look_names())
        dpg.set_value(f"vj_look{i}", d["look"])
        dpg.configure_item(f"vj_fx{i}", items=list(app.eng.names))
        dpg.set_value(f"vj_fx{i}", d.get("effect", ""))
        dpg.configure_item(f"vj_fxrow{i}", show=eff)
        dpg.configure_item(f"vj_palrow{i}", show=eff)
        dpg.configure_item(f"vj_fxcolrow{i}", show=eff)
        dpg.configure_item(f"vj_colrow{i}", show=not eff)
        dpg.set_value(f"vj_fxcol{i}", d.get("fx_colours") or OWN_COLS)
        dpg.configure_item(f"vj_pal{i}", items=pals)
        dpg.set_value(f"vj_pal{i}", d.get("palette") or OWN_PAL)
        dpg.configure_item(f"vj_textrow{i}", show=d["look"] == "Text")
        dpg.set_value(f"vj_text{i}", d.get("text", ""))
        glsl = getattr(lk, "glsl", None) if lk else None
        dpg.configure_item(f"vj_imgrow{i}", show=d["look"] == "Image" or bool(glsl and (
            "picture" in glsl or "picture" in (d.get("channels") or []))))
        dpg.configure_item(f"vj_chrow{i}", show=bool(glsl))
        if glsl:
            from native import vj_glsl
            own = vj_glsl.channels_of(glsl)
            ch = list(d.get("channels") or ["", "", "", ""])
            for k in range(4):
                first = f"file: {own[k]}"
                dpg.configure_item(f"vj_ch{i}_{k}", items=[first] + list(vj_glsl.CHANNELS))
                dpg.set_value(f"vj_ch{i}_{k}", ch[k] or first)
        dpg.set_value(f"vj_imgname{i}", os.path.basename(d.get("image") or "") or "none")
        dpg.configure_item(f"vj_vidhead{i}", show=not eff)
        kind = s.get("kind", "none")
        dpg.set_value(f"vj_src{i}", dict(vj.SOURCES).get(kind, "no video"))
        dpg.configure_item(f"vj_srcpick{i}", show=kind in ("file", "webcam", "screen", "stream"))
        dpg.configure_item(f"vj_pause{i}", show=kind != "none")
        dpg.configure_item(f"vj_srcname{i}", show=kind in ("webcam", "screen") and bool(s.get("name")))
        if s.get("name"):
            dpg.configure_item(f"vj_srcname{i}", items=[s["name"]])
            dpg.set_value(f"vj_srcname{i}", s["name"])
        dpg.configure_item(f"vj_url{i}", show=kind == "stream")
        files = [f for f in (s.get("files") or []) if f]
        dpg.configure_item(f"vj_cliprows{i}", show=kind == "file")
        dpg.configure_item(f"vj_clips{i}", items=[os.path.basename(f) for f in files])
        dpg.set_value(f"vj_clips{i}", os.path.basename(vj.clip_path(s)) if files or s.get("path") else "")
        for tag, key in (("vj_csp", "speed"), ("vj_cin", "in"), ("vj_cout", "out")):
            num.set(f"{tag}{i}", float(s.get(key, 0.0)))
        dpg.set_value(f"vj_adv{i}", dict(vj.ADVANCE).get(s.get("advance", "off"), "by hand"))
        for tag, key in (("vj_lvl", "level"), ("vj_amt", "amount"), ("vj_spd", "speed"), ("vj_kal", "kaleido"),
                         ("vj_hue", "hue"), ("vj_trl", "trails"), ("vj_blr", "blur")):
            num.set(f"{tag}{i}", d[key])
        dpg.set_value(f"vj_col{i}", d["colours"])
        dpg.set_value(f"vj_mir{i}", bool(d["mirror"]))
        dpg.set_value(f"vj_str{i}", bool(d["strobe"]))
        dpg.set_value(f"vj_rto{i}", d["react"]["to"])
        dpg.set_value(f"vj_rwhat{i}", d["react"]["what"])
        num.set(f"vj_rdep{i}", float(d["react"]["depth"]))
        dpg.configure_item(f"vj_mut{i}", show=bool(lk) and lk.family == "flame")
        dpg.configure_item(f"vj_edit{i}", show=bool(lk) and lk.family == "yours")
        dpg.configure_item(f"vj_flamerow{i}", show=d["look"] in o["flames"])
        dpg.configure_item(f"vj_pre{i}", items=sorted(o["presets"]))
        desc = "an effect of the studio's, on the shape itself (speed and amount are its Speed and Intensity)" if eff \
            else (lk.desc if lk else "")
        dpg.set_value(f"vj_desc{i}", desc)
    num.set("vj_fader", float(o["fader"]))


def _fit(img, w, h):
    ih, iw = img.shape[:2]
    if (ih, iw) == (h, w):
        return img
    ys = (np.arange(h) * ih // h).clip(0, ih - 1)
    xs = (np.arange(w) * iw // w).clip(0, iw - 1)
    return img[ys][:, xs]


def _preview(app, i):
    if not dpg.is_item_visible(f"vj_pv{i}"):
        return
    img = vj.deck_canvas(app, i)
    if img is None:
        return
    img = _fit(img, PV_W, PV_H)
    fader = float(vj.options(app)["fader"])
    live = ((1.0 - fader) if i == 0 else fader) if i < 2 else 1.0  # the deck off the mix shown dimmer: the cue
    live *= vj.knob_value(app, i, "level")
    k = 0.45 + 0.55 * min(1.0, live * 2.0)
    rgba = np.concatenate([img.astype(np.float32) * (k / 255.0), np.ones((PV_H, PV_W, 1), np.float32)], -1)
    dpg.set_value(f"vj_tex{i}", rgba.ravel())


def _out_preview(app):
    out = getattr(app, "_vj_out", None)
    if out is None or not dpg.is_item_visible("vj_out"):
        return
    img = _fit(out, OUT_N, OUT_N).astype(np.float32) / 255.0
    if not vj.on(app):
        img = img * 0.45                                            # off air: shown dim - it is what would go on
    dpg.set_value("vj_out_tex", np.concatenate([img, np.ones((OUT_N, OUT_N, 1), np.float32)], -1).ravel())


def poll(app):
    """Each frame: the decks drawn while on air or while the frame is open; their previews, the output and the
    beat; the fader shown where an auto-mix has it; a look dealt by shuffle shown; a settled change saved."""
    _flush_save(app)
    if not dpg.does_item_exist(TAG):
        return
    shown = dpg.is_item_shown(TAG)
    if not (vj.on(app) or shown):
        if getattr(app, "_vj_open", False):
            vj.close(app)                                           # nothing needs the sources: webcams off
            app._vj_open = False
        return
    app._vj_open = True
    app._vj_preview = {i for i in range(vj.DECKS) if dpg.is_item_visible(f"vj_pv{i}")} if shown else set()
    if time.monotonic() - getattr(app, "_vj_files_at", 0.0) > 1.0:     # the project's own looks, as they are saved
        app._vj_files_at = time.monotonic()
        before = set(vj_looks.LOOKS)
        app._vj_file_errs = vj_looks.load_user(app.project, allow_py=py_allowed(app))
        if any(e == vj_looks.NOT_ALLOWED for _, e in app._vj_file_errs) and shown:
            _ask_py(app)
        if set(vj_looks.LOOKS) != before:
            app._vj_dirty = True
            app._vj_thumbs = None if not dpg.is_item_shown(BROWSE) else app._vj_thumbs
    vj.update(app)
    _thumbs(app)
    if shown:
        for i in range(vj.DECKS):
            _preview(app, i)
        _out_preview(app)
        p = float(getattr(app, "_vj_pulse", 0.0))
        g = int(60 + 195 * p)
        dpg.configure_item("vj_beat", fill=(g, int(60 + 120 * p), 60, 255))
        o = vj.options(app)
        if abs(float(dpg.get_value("vj_fader")) - float(o["fader"])) > 1e-3 and not num.busy():
            num.set("vj_fader", float(o["fader"]))
        if getattr(app, "_vj_knobs_moved", False) and not num.busy():       # MIDI or a modulator moved a knob
            app._vj_knobs_moved = False
            for i in range(vj.DECKS):
                d = o["decks"][i]
                for tag, key in (("vj_lvl", "level"), ("vj_amt", "amount"), ("vj_spd", "speed"), ("vj_kal", "kaleido"),
                                 ("vj_hue", "hue"), ("vj_trl", "trails"), ("vj_blr", "blur")):
                    num.set(f"{tag}{i}", d[key])
        if getattr(app, "_vj_dirty", False):
            app._vj_dirty = False
            refresh(app)
        bars, where = vj.bar_count(app)
        tempo = f"{vj._tempo(app):g} bpm, bar {int(bars) + 1} ({where})"
        if dpg.get_value("vj_tempo") != tempo:
            dpg.set_value("vj_tempo", tempo)
        errs = [f"deck {LETTER[i]}: {r.error}" for i, r in enumerate(vj._runs(app)) if r.error]
        errs += [f"looks/{f}: {e}" for f, e in getattr(app, "_vj_file_errs", [])]
        words = "; ".join(errs) if errs else ("on air" if vj.on(app) else "off air - the effect shows")
        if dpg.get_value("vj_words") != words:
            dpg.set_value("vj_words", words)
# AI: end
